/**
 * Finds `rel=preload` links in this site's Nginx configuration that name a
 * file the live build does not contain.
 *
 * Why it exists (GEO audit #13, B5): the /homelab/ location announced three
 * font preloads in its `Link` header, written into the vhost by hand. Astro
 * Fonts names each file after a content hash; the hashes changed on
 * 2026-11-06, the vhost did not, and for two weeks every visit to /homelab/
 * asked for three fonts that 404ed. That header is generated by the build now
 * (`src/integrations/post-build/homelab-preload.ts`), but a vhost is edited by
 * hand and outside the repository, so nothing stops the next hand-written
 * preload from going stale the same way. `deploy-live.mjs` runs this after
 * every reload, against `nginx -T`, and prints a notice; it never fails the
 * deploy, because the site itself is fine and only a hint is wrong.
 *
 * Kept out of `deploy-live.mjs` so it can be unit-tested: importing that
 * script runs a deploy.
 *
 * @module
 */

import fs from "node:fs";
import path from "node:path";

/**
 * The server_name values that mark a dumped file as this site's own, compared
 * as whole names (a Set lookup, not a substring test).
 */
const SITE_SERVER_NAMES = new Set(["jmrp.io"]);
/** Hosts whose absolute URLs are this site's own files. */
const SITE_HOSTS = new Set(["jmrp.io", "www.jmrp.io"]);

/**
 * Splits an `nginx -T` dump into one section per configuration file.
 *
 * `nginx -T` prints each file once, after a `# configuration file <path>:`
 * line, which is what lets a finding name the file to edit.
 *
 * @param {string} dump - Standard output of `nginx -T`.
 * @returns {{ file: string, body: string }[]} Sections in dump order; text
 *   before the first header is dropped (it is the `nginx -t` banner).
 */
export function splitNginxDump(dump) {
  const sections = [];
  let current = null;
  for (const line of dump.split("\n")) {
    const header = /^# configuration file (.+):$/.exec(line);
    if (header) {
      current = { file: header[1], lines: [] };
      sections.push(current);
    } else if (current) {
      current.lines.push(line);
    }
  }
  return sections.map((section) => ({
    file: section.file,
    body: section.lines.join("\n"),
  }));
}

/**
 * Removes whole-line comments, so a URL quoted in an explanatory comment (the
 * old vhost comment told the reader where to refresh the hashes from) is not
 * reported as a live preload. A `#` after a directive is left alone: inside a
 * quoted header value it is ordinary text, such as a URL fragment.
 *
 * @param {string} body - The text of one configuration file.
 * @returns {string} The same text without its comment lines.
 */
function stripCommentLines(body) {
  return body
    .split("\n")
    .filter((line) => !/^\s*#/.test(line))
    .join("\n");
}

/**
 * Whether the parameters of one Link entry carry `rel=preload`, among other
 * relation types or alone, quoted or not (`rel=preload`, `rel="preload"`,
 * `rel=\\"preload\\"` as written inside a quoted nginx value).
 *
 * A parse rather than one regular expression: the pattern that matched every
 * spelling had overlapping quantifiers and could backtrack (Sonar S5852).
 *
 * @param {string} params - The text after the entry's `>`, up to its end.
 * @returns {boolean} Whether one of its `rel` values is `preload`.
 */
function hasPreloadRel(params) {
  for (const part of params.split(";")) {
    const eq = part.indexOf("=");
    if (eq === -1 || part.slice(0, eq).trim().toLowerCase() !== "rel") {
      continue;
    }
    const value = part
      .slice(eq + 1)
      .replaceAll(/[\\"]/g, "")
      .trim();
    return value
      .split(" ")
      .some((type) => type.trim().toLowerCase() === "preload");
  }
  return false;
}

/**
 * Extracts the target of every `rel=preload` link in a piece of Nginx config.
 *
 * Looks for the RFC 8288 shape `<target>; ...; rel=preload` wherever it is:
 * in a literal `add_header Link` value and in the values of a `map` whose
 * variable a `Link` header carries (the generated /homelab/ map), with the
 * `rel` value bare, quoted or escape-quoted. Matching the link shape, not the
 * word, is what keeps the `preload` token of an HSTS header out.
 *
 * @param {string} text - Nginx configuration text, comments included or not.
 * @returns {string[]} The targets, in order, as written.
 */
export function extractPreloadTargets(text) {
  const targets = [];
  // The parameters of a link run from its `>` to the comma that starts the
  // next link; a newline or the closing `'` of a header value also ends them.
  // No parameter value this site uses contains a comma.
  const link = /<([^<>\s]+)>([^<,'\n]*)/g;
  for (const match of stripCommentLines(text).matchAll(link)) {
    if (hasPreloadRel(match[2])) targets.push(match[1]);
  }
  return targets;
}

/**
 * Decides whether a configuration file belongs to this site.
 *
 * `nginx -T` dumps every vhost on the box, and a relative preload in another
 * site's config says nothing about this build. A file counts as this site's
 * when it sits in the delivered snippets directory, or when it declares
 * `server_name jmrp.io` (compared as a whole token, so `bio.jmrp.io` does
 * not count).
 *
 * @param {{ file: string, body: string }} section - One dumped file.
 * @param {string} [snippetsDir] - The delivered snippets directory.
 * @returns {boolean} Whether its relative preloads are this site's files.
 */
function isOwnSection(section, snippetsDir) {
  if (snippetsDir) {
    const rel = path.relative(path.resolve(snippetsDir), section.file);
    if (rel && !rel.startsWith("..") && !path.isAbsolute(rel)) return true;
  }
  for (const match of stripCommentLines(section.body).matchAll(
    // One whitespace character, then the rest up to `;`: `\s+([^;]+)` let
    // both quantifiers claim the same spaces (Sonar S5852).
    /\bserver_name\s([^;]*);/g,
  )) {
    // Whole names compared for equality, never a substring test, so
    // `bio.jmrp.io` or `jmrp.io.example` cannot pass for this site.
    const names = match[1].trim().split(/\s+/);
    if (names.some((name) => SITE_SERVER_NAMES.has(name))) return true;
  }
  return false;
}

/**
 * Resolves a preload target to a path under the build, or `null` when it is
 * not one of this site's files (another host, a protocol-relative URL).
 *
 * @param {string} target - The `<...>` content of a link.
 * @param {boolean} ownSection - Whether a relative target means this site.
 * @returns {string | null} The URL path, starting with `/`.
 */
function sitePath(target, ownSection) {
  if (target.startsWith("/") && !target.startsWith("//")) {
    return ownSection ? target : null;
  }
  try {
    const url = new URL(target);
    return SITE_HOSTS.has(url.hostname) ? url.pathname : null;
  } catch {
    return null;
  }
}

/**
 * Lists the preloads in an `nginx -T` dump whose file is not in the build.
 *
 * A path is looked up in `distDir` after dropping its query and fragment and
 * decoding it; a path that would leave `distDir` once decoded counts as
 * missing, since nothing under the document root can answer it. A directory
 * path counts as present when it has an `index.html`.
 *
 * @param {string} dump - Standard output of `nginx -T`.
 * @param {{ distDir: string, snippetsDir?: string }} options - The live build
 *   directory, and the directory the generated snippets are delivered to.
 * @returns {{ file: string, target: string }[]} Each stale preload with the
 *   configuration file it is written in, duplicates removed.
 */
export function findStalePreloads(dump, { distDir, snippetsDir }) {
  const root = path.resolve(distDir);
  const stale = [];
  const seen = new Set();
  for (const section of splitNginxDump(dump)) {
    const own = isOwnSection(section, snippetsDir);
    for (const target of extractPreloadTargets(section.body)) {
      const urlPath = sitePath(target, own);
      if (urlPath === null) continue;
      const key = `${section.file}\n${target}`;
      if (seen.has(key)) continue;
      seen.add(key);
      if (!existsInBuild(root, urlPath)) {
        stale.push({ file: section.file, target });
      }
    }
  }
  return stale;
}

/**
 * Tells whether a URL path names a file in the build.
 *
 * @param {string} root - Absolute build directory.
 * @param {string} urlPath - Path part of a URL, starting with `/`.
 * @returns {boolean} Whether the file (or the directory's index) exists.
 */
function existsInBuild(root, urlPath) {
  let decoded;
  try {
    decoded = decodeURIComponent(urlPath.split(/[?#]/, 1)[0]);
  } catch {
    return false;
  }
  const filePath = path.resolve(root, `.${decoded}`);
  const rel = path.relative(root, filePath);
  if (rel.startsWith("..") || path.isAbsolute(rel)) return false;
  const candidate = decoded.endsWith("/")
    ? path.join(filePath, "index.html")
    : filePath;
  try {
    return fs.statSync(candidate).isFile();
  } catch {
    return false;
  }
}

/**
 * Formats the end-of-deploy notice for stale preloads.
 *
 * @param {{ file: string, target: string }[]} stale - Output of
 *   {@link findStalePreloads}.
 * @returns {string[]} Lines to print, empty when nothing is stale.
 */
export function formatPreloadNotice(stale) {
  if (stale.length === 0) return [];
  return [
    `⚠ ${stale.length} rel=preload link(s) in the Nginx config name a file that is not in dist/:`,
    ...stale.map(({ file, target }) => `    ${target}  (${file})`),
    "  Every visit to a page that announces them requests a 404 (a console error and a Lighthouse Best Practices deduction).",
    "  Remove the hand-written preload, or announce it through a build-generated map as /homelab/ does with $jmrp_homelab_preload (src/integrations/post-build/homelab-preload.ts).",
  ];
}
